export const fetchUrl = async (url:string,kind:string,isUpdate:boolean = false) => {
    let baseUrl = process.env.REACT_APP_CHART_URL;
    
    try {
        return new Promise((resolve, reject) => {
            const params = new URLSearchParams({
                ticker: kind,
                limit: isUpdate ? '1' : '0'
            }); 
            fetch(`${baseUrl}${url}?${params}`,{
                method:"GET",
                headers: {
                    'Content-Type': 'application/json'
                }
            })
            .then((res:Response)=> res.json())
            .then((data:any) => {
                resolve(data.result); // 데이터를 resolve하여 외부로 전달
            }).catch((error:any) => {
                console.log('get api error', error);
                reject(error); // 에러를 reject하여 외부에서 처리
            });
        });
    } catch (error) {
        console.log('get api error', error);
        throw error;
    }
};