export const percentFormat = (value: number) => {
    if(value > 0){
        return `+${value.toFixed(2)}%`;
    } else if(value < 0){
        return `${value.toFixed(2)}%`;
    } else {
        return `0%`;
    }
}

export const colorFormat = (value: number) => {
    if(value > 0){
        return 'text-green';
    } else if(value < 0){
        return 'text-red';
    } else {
        return 'text-gray';
    }
}

export const numberFormat = (value: number) => {
    return Intl.NumberFormat('en-US', {
        style: 'decimal',
        // currency: 'USD',
        // minimumFractionDigits: 2,
        // maximumFractionDigits: 2,
    }).format(value);
}

export const checkDecimal = (number: number) => {

    const decimalPlaces = Number(number.toString().split(".")[1]?.length) || 0;
    const decimalScale = decimalPlaces > 0 ? Math.pow(10, -decimalPlaces).toFixed(decimalPlaces) : 1;
    
    return {decimalPlaces,decimalScale}
}