import { createBrowserRouter } from "react-router-dom";
import DefaultLayout from "../screen/DefaultLayout";
import MainScreen from "../screen/MainScreen";
import MypageScreen from "../screen/MypageScreen";
import ChartDetailScreen from "../screen/ChartDetailScreen";
console.log(process.env.PUBLIC_URL,process.env.NODE_ENV);
export const router = createBrowserRouter(
    [
        {
            path: '/',
            element: <DefaultLayout />,
            children: [
                {
                    path: '',
                    element: <MainScreen />
                },
                {
                    path: "mypage",
                    element: <MypageScreen />
                },
                {
                    path: "ai-chart/:symbol",
                    element: <ChartDetailScreen />
                }
            ]
        },
    ],
    {
        basename: process.env.NODE_ENV === "production" ? "/walletconnect" : "/" // GitHub 저장소 이름
    }
);