export const walletText = (walletName:string,action:string)  => {
    if(action === 'prepare'){
        return {
            title: 'Comming Soon',
            content: 'Currently being prepared',
        };
    }else if(action === 'uninstalled'){
        return {
            title: `Need to install ${walletName} Wallet`,
            content: `The ${walletName} Google extension is not installed.<br/> Would you like to go to the installation page?`,
            link:setLink(walletName)
        };
    }else if(action === 'noWallet'){
        return {
            title: `There is no ${walletName} Wallet`,
            content: 'The wallet is installed but no wallet has been created.<br/>Please create a wallet or recover an existing wallet.<br/> Please try connecting again after completing wallet setup.',
        };
    }else if(action === 'connect'){
        return {
            title: `Your wallet has been connected!`,
            content: ``,
        };
    }else if(action === 'userRejected'){
        return {
            title: `Please follow the instructions to create a wallet`,
            content: `Please follow the instructions to create a wallet. <br/>You will need to download the app and set up a new account.`,
        };
    }
};


const setLink = (walletName:string) => {
    if(walletName === 'Phanthom'){
        return 'https://phantom.app/download'
    }else if(walletName === 'OKX'){
        return 'https://chromewebstore.google.com/detail/okx-wallet/mcohilncbfahbmgdjkbpemcciiolgcge'
    }
}