import { CopyToClipboard } from 'react-copy-to-clipboard';
import { useState, useContext } from 'react';
import { WindowContext } from '../../contexts/windowContext';
import { ButtonGreen, ButtonSmall } from '../../styles/common/Button';
import { theme } from '../../styles/theme';

export default function CopyButton({ text, needImg, needSmall = false }: { text: string, needImg: boolean, needSmall: boolean }) {
    const [isCopied, setIsCopied] = useState(false);
    const { isMobile, isLaptop } = useContext(WindowContext);
    return (
        <>
            {
                needSmall ?
                    <CopyToClipboard text={text} onCopy={
                        () => {
                            setIsCopied(true);
                            setTimeout(() => {
                                setIsCopied(false);
                            }, 5000);
                        }
                    }>
                        <ButtonSmall bgColor={theme.color.mainGreen} textColor={theme.color.black} borderColor={theme.color.mainGreen}>
                            <span>
                                {isCopied ? "COPIED!" : "COPY"}
                            </span>
                        </ButtonSmall>
                    </CopyToClipboard>
                    :
                    <CopyToClipboard text={text} onCopy={
                        () => {
                            setIsCopied(true);
                            setTimeout(() => {
                                setIsCopied(false);
                            }, 5000);
                        }
                    }>
                        <ButtonGreen>
                            {needImg && <img src={theme.icon.copy} alt="copy" />}
                            {isCopied ? "COPIED!" : "COPY"}
                        </ButtonGreen>
                    </CopyToClipboard>
            }
        </>
    )
}