    const initSeries = async (chart: IChartApi) => {
        seriesConfigsRef.current.forEach((item: any) => {
            if (item['series'] && item['series'].length > 0) {
                item['series'].forEach((series: any) => {
                    // console.log('item', item.key,series);
                    seriesRef.current[series.name] = chartInstance.createSeries(chart, series.type, series.option);
                    series.name = seriesRef.current[series.name];
                    let { decimalPlaces, decimalScale } = checkDecimal(candleInfo.afterLastCandle?.close || 0);
                    chartInstance.setPriceFormat(series.name,series.option,{decimalPlaces,decimalScale});
                })
            }
            if (item.key === "PINK" || item.key === "AO") {
                chartAPI.getIndicator(symbol || "", isHeikin, item)
            }
        })
        // console.log('seriesConfigs', seriesConfigs);
    }

    useEffect(() => {
        const initChart = async () => {
            if (!chartContainerRef.current) return;

            const chart = chartInstance.createChart(chartContainerRef.current);
            seriesRef.current.chart = chart;
            const candlestickSeries = chartInstance.createSeries(chart, 'candle', 'candleOptions');
            seriesRef.current.candlestickSeries = candlestickSeries;
            // getCandle이 완료될 때까지 기다림
            await chartAPI.getCandle(symbol || '', candlestickSeries, isHeikin);
            setCandleLength(candlestickSeries.data().length);
            
            if (candlestickSeries.data().length > 0) {
                setCandleInfo({
                    afterLastCandle: candlestickSeries.data()[candlestickSeries.data().length - 1],
                    beforeLastCandle: candlestickSeries.data()[candlestickSeries.data().length - 2],
                    percent: ((candlestickSeries.data()[candlestickSeries.data().length - 1].close - candlestickSeries.data()[candlestickSeries.data().length - 2].close) / candlestickSeries.data()[candlestickSeries.data().length - 2].close) * 100
                })
            }
            let { decimalPlaces, decimalScale } = checkDecimal(candlestickSeries.data()[candlestickSeries.data().length - 1].close);
            // console.log('decimalPlaces', decimalPlaces);
            // console.log('decimalScale', decimalScale);
            chartInstance.setPriceFormat(seriesRef.current.candlestickSeries, 'candleOptions', { decimalPlaces, decimalScale });
            // getCandle 완료 후 initSeries 실행
            await initSeries(chart);
            await chartAPI.getSignalMarkers(symbol || '', candlestickSeries, 'none');
        };

        // 비동기 함수 실행
        initChart().catch(console.error);

        const updateInterval = setInterval(async () => {
            console.log('updateInterval');
            let isHeikin = getCheckList('HEI');
            let checkedList = newCheckList.filter((item: any) => item.checked).map((item: any) => item.value);
            function getSeries(id: string) {
                return seriesConfigsRef.current.find((obj: any) => obj.key == id)
            }
            await chartAPI.updateChart(seriesConfigsRef.current)
            await chartAPI.getCandle(symbol || '', seriesRef.current.candlestickSeries, false);
            await chartAPI.getCandle(symbol || '', seriesRef.current.candlestickSeries, isHeikin);
            seriesRef.current.candlestickSeries.setData(seriesRef.current.candlestickSeries.data())
            newCheckList.forEach(async (chkBox) => {
                await setEachIndicator(chkBox.value, chkBox.checked, seriesRef.current.candlestickSeries);
            })
            await chartAPI.getSignalMarkers(symbol || '', seriesRef.current.candlestickSeries, 'none')
            chartAPI.displayCheckStatus('pro', checkedList, seriesConfigsRef.current)
        }, 60 * 1000 * 5);

        return () => {
            if (seriesRef.current.chart) {
                seriesRef.current.chart.remove();
            }
            clearInterval(updateInterval);
        }
    }, []);

    async function setEachIndicator(id: string, checked: boolean, candlestickSeries: any) {
        let isHeikin = getCheckList('HEI');

        function getSeries(id: string) {
            return seriesConfigsRef.current.find((obj: any) => obj.key == id)
        }
        let chartObj = getSeries(id)
        if (chartObj && chartObj.hasOwnProperty('series')) {
            let seriesObj = chartObj.series;
            if (checked) {
                if (id == "TREND") {
                    await chartAPI.getTrendLine(symbol || '', chartObj);
                } else if (id == "MACD") {
                    await chartAPI.getMACD(symbol || '', isHeikin, chartObj);
                } else if (id == "RSI") {
                    let macdSeries = getSeries("MACD").series
                    let isMacdLoad = await chartAPI.isInitLoad(macdSeries, isHeikin, 'MACD')
                    // console.log('isMacdLoad',isMacdLoad);
                    if (isMacdLoad) {
                        await chartAPI.getMACD(symbol || '', isHeikin, getSeries("MACD"), true);
                    }

                    await chartAPI.getRSI(symbol || '', isHeikin, chartObj);
                } else {
                    await chartAPI.getIndicator(symbol || '', isHeikin, chartObj);
                }
            } else {
                await chartAPI.resetIndicator(seriesObj)
            }
        } else {
            if (id == "SR") {
                await chartAPI.getSr(chartObj.url, symbol || '', candlestickSeries, checked)
            }
        }
    }

    const handleCheck = async (index: number) => {
        let updatedCheckList = [...newCheckList];
        updatedCheckList[index].checked = !updatedCheckList[index].checked;
        setNewCheckList(updatedCheckList);

        let checkedValue = updatedCheckList[index].value;
        let totalCheckList = updatedCheckList.map((item: any) => item.value);
        let checkedList = updatedCheckList.filter((item: any) => item.checked).map((item: any) => item.value);
        let isHeikin = getCheckList('HEI');

        function getSeries(id: string) {
            return seriesConfigsRef.current.find((obj: any) => obj.key == id)
        }
        function getChkBox(id: string, checked: boolean) {
            // return updatedCheckList.find((obj:any)=> obj.value == id)
            updatedCheckList = updatedCheckList.map((item: any) => {
                if (item.value == id) {
                    item.checked = checked;
                }
                return item;
            })
            setNewCheckList(updatedCheckList);
        }
        if (checkedValue == 'HEI' || checkedValue == "ALL") {
            await chartAPI.getCandle(symbol || '', seriesRef.current.candlestickSeries, isHeikin);

            updatedCheckList.forEach(async (chkBox) => {
                if (checkedValue == "ALL") {
                    const newCheckedState = updatedCheckList[index].checked;
                    updatedCheckList = updatedCheckList.map((item: any) => ({
                        ...item,
                        checked: newCheckedState
                    }));
                    setNewCheckList(updatedCheckList);
                    chkBox.checked = newCheckedState;
                }
                await setEachIndicator(chkBox.value, chkBox.checked, seriesRef.current.candlestickSeries);
            })
            checkedList = updatedCheckList.filter((item: any) => item.checked).map((item: any) => item.value);
            seriesRef.current.candlestickSeries.setData(seriesRef.current.candlestickSeries.data())
        } else {
            await setEachIndicator(checkedValue, updatedCheckList[index].checked, seriesRef.current.candlestickSeries);
        }
        // all status check
        let isAllChecked = totalCheckList.filter(el => el != 'ALL').every(val => updatedCheckList.find((item: any) => item.value == val)?.checked === true)
        getChkBox("ALL", isAllChecked)
        // for priceScale after check rsi,macd
        chartAPI.setPriceScale(checkedList, { 'RSI': getSeries('RSI'), "MACD": getSeries("MACD") }, seriesRef.current.chart)
        // display check status
        chartAPI.displayCheckStatus('pro', checkedList, seriesConfigsRef.current)
        // console.log('checkList.find((id)=> id == this.id)',getChkBox(this.id));
        getChkBox(checkedValue, updatedCheckList[index].checked)

    }
    const handleTime = (time: string) => {
        if (time === 'day') {
            seriesRef.current.chart.timeScale().setVisibleLogicalRange({

                from: candleLength - 24,
                to: candleLength
            })
        } else if (time === 'week') {
            seriesRef.current.chart.timeScale().setVisibleLogicalRange({
                from: candleLength - 168,
                to: candleLength
            })
        } else if (time === 'month') {
            seriesRef.current.chart.timeScale().fitContent();
        }
    }
